const items = $input.all();

return items.map(item => {
  // Webhook payloads are nested in the 'body' object
  const data = item.json.body || item.json; 

  const fuelVarianceLiters = data.actual_fuel_liters - data.expected_fuel_liters;
  const wastedFuelCostZAR = fuelVarianceLiters * 23.50;
  const idleHours = data.idle_time_mins / 60;
  const idlePenaltyZAR = idleHours * 350.00;
  const totalFinancialLeakage = wastedFuelCostZAR + idlePenaltyZAR;

  // Calculate Boolean threshold
  const isHighRisk = (data.variance_percent > 15.0) || (data.idle_time_mins > 120);

  return {
    json: {
      ...data,
      fuel_variance_liters: fuelVarianceLiters.toFixed(2),
      wasted_fuel_zar: wastedFuelCostZAR.toFixed(2),
      idle_hours: idleHours.toFixed(2),
      idle_penalty_zar: idlePenaltyZAR.toFixed(2),
      total_leakage_zar: totalFinancialLeakage.toFixed(2),
      requires_escalation: isHighRisk
    }
  };
});
